"use client";

/**
 * Answer select: a question sits in a pill, the answer writes itself word by
 * word, then one phrase gets selected and a small toolbar opens under it.
 *
 * Written by Better Design. Painted from the theme prop, so the selection
 * takes the product's primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, springs, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600"], subsets: ["latin"] });

const PILL_FRAMES = 16;
const WORDS_FROM = 20;
/** Frames the whole answer takes to write, however long it is. */
const WORDS_BUDGET = 56;
const SELECT_AT = 88;
const SELECT_FRAMES = 16;
const TOOLBAR_AT = 102;

export interface AnswerSelectProps {
  /** The question, shown in the pill at the top. */
  question?: string;
  /** The answer that writes itself below. */
  answer?: string;
  /** A phrase inside the answer that gets selected. Must match the answer's text exactly. */
  selected?: string;
  /** The buttons on the floating toolbar. The last one takes the primary colour. */
  actions?: string[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

interface Word {
  text: string;
  start: number;
  end: number;
}

const splitWords = (text: string): Word[] =>
  Array.from(text.matchAll(/\S+/g), (m) => ({ text: m[0], start: m.index ?? 0, end: (m.index ?? 0) + m[0].length }));

function Toolbar({ theme, actions, t }: { theme: VideoTheme; actions: string[]; t: number }) {
  return (
    <div
      style={{
        position: "absolute",
        left: -10,
        top: "calc(100% + 30px)",
        zIndex: 2,
        display: "flex",
        alignItems: "center",
        padding: 8,
        gap: 4,
        borderRadius: theme.radius * 1.4,
        background: theme.popover,
        border: `1px solid ${theme.border}`,
        boxShadow: `0 24px 48px -18px ${withAlpha(theme.foreground, 0.28)}`,
        opacity: Math.min(1, t * 1.6),
        transform: `translateY(${(1 - t) * -12}px) scale(${0.92 + 0.08 * t})`,
        transformOrigin: "left top",
        whiteSpace: "nowrap",
        fontSize: 28,
        fontWeight: 500,
        letterSpacing: "-0.005em",
      }}
    >
      {actions.map((action, i) => {
        const last = i === actions.length - 1;
        return (
          <div key={action} style={{ display: "flex", alignItems: "center", gap: 4 }}>
            {i > 0 && !last ? <div style={{ width: 1, height: 30, background: theme.border, margin: "0 4px" }} /> : null}
            <div
              style={{
                padding: "12px 20px",
                borderRadius: theme.radius,
                color: last ? theme.primaryForeground : theme.popoverForeground,
                background: last ? theme.primary : withAlpha(theme.primary, 0),
                marginLeft: last ? 8 : 0,
              }}
            >
              {action}
            </div>
          </div>
        );
      })}
    </div>
  );
}

/** An answer writes itself under a question, then one phrase is selected. */
export function AnswerSelect({
  question = "How do I keep a team aligned on design?",
  answer = "Write the decisions down in one shared place, review them each week, and let every new screen start from the same small set of components.",
  selected = "start from the same small set of components",
  actions = ["Copy", "Quote", "Ask about this"],
  theme: themeOverride,
  font,
}: AnswerSelectProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);

  const words = splitWords(answer);
  const perWord = Math.min(4, WORDS_BUDGET / Math.max(1, words.length));
  const from = selected ? answer.indexOf(selected) : -1;
  const to = from + selected.length;
  const picked = words.map((w, i) => ({ ...w, i })).filter((w) => from >= 0 && w.end > from && w.start < to);
  const firstSel = picked[0]?.i ?? -1;
  const lastSel = picked[picked.length - 1]?.i ?? -1;

  const pill = easings.out(progress(frame, 0, PILL_FRAMES));
  const sweep = easings.inOut(progress(frame, SELECT_AT, SELECT_FRAMES));
  const toolbar = spring({ frame: frame - TOOLBAR_AT, fps, config: springs.snappy });

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div style={{ width: 1400, display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 72 }}>
        <div
          style={{
            padding: "20px 34px",
            borderRadius: 999,
            background: theme.secondary,
            border: `1px solid ${theme.border}`,
            color: theme.secondaryForeground,
            fontSize: 36,
            fontWeight: 500,
            letterSpacing: "-0.01em",
            opacity: pill,
            transform: `translateY(${(1 - pill) * 18}px)`,
          }}
        >
          {question}
        </div>
        <div style={{ fontSize: 64, fontWeight: 500, lineHeight: 1.38, letterSpacing: "-0.02em", color: theme.foreground }}>
          {words.map((word, i) => {
            const t = easings.out(progress(frame, WORDS_FROM + i * perWord, 9));
            const inSel = i >= firstSel && i <= lastSel && firstSel >= 0;
            const fill = inSel ? Math.min(1, Math.max(0, sweep * picked.length - (i - firstSel))) : 0;
            const first = i === firstSel;
            const last = i === lastSel;
            return (
              <span
                key={`${word.start}`}
                style={{
                  position: "relative",
                  display: "inline-block",
                  marginRight: "0.26em",
                  opacity: t * (inSel || firstSel < 0 ? 1 : 1 - 0.5 * sweep),
                  transform: `translateY(${(1 - t) * 14}px)`,
                  filter: `blur(${(1 - t) * 6}px)`,
                }}
              >
                {inSel ? (
                  <span
                    style={{
                      position: "absolute",
                      left: first ? "-0.06em" : -2,
                      right: last ? "-0.06em" : "-0.26em",
                      top: "0.04em",
                      bottom: "0.02em",
                      // Opaque, so neighbouring words meet without a seam.
                      background: `linear-gradient(${withAlpha(theme.primary, 0.2)}, ${withAlpha(theme.primary, 0.2)}), ${theme.background}`,
                      borderRadius: `${first ? 8 : 0}px ${last ? 8 : 0}px ${last ? 8 : 0}px ${first ? 8 : 0}px`,
                      clipPath: `inset(0 ${(1 - fill) * 100}% 0 0)`,
                    }}
                  />
                ) : null}
                {first || last ? (
                  <span
                    style={{
                      position: "absolute",
                      [first ? "left" : "right"]: "-0.08em",
                      top: "0.02em",
                      bottom: 0,
                      width: 4,
                      borderRadius: 2,
                      background: theme.primary,
                      opacity: first ? Math.min(1, sweep * 8) : unitStep(sweep),
                    }}
                  >
                    <span style={{ position: "absolute", left: -6, [first ? "top" : "bottom"]: -12, width: 16, height: 16, borderRadius: 8, background: theme.primary }} />
                  </span>
                ) : null}
                <span style={{ position: "relative" }}>{word.text}</span>
                {last && toolbar > 0.001 ? <Toolbar theme={theme} actions={actions} t={toolbar} /> : null}
              </span>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
}

/** The end handle shows once the sweep reaches it. */
const unitStep = (sweep: number): number => Math.min(1, Math.max(0, (sweep - 0.9) * 10));
